    if MULTI:
        head = 'I am calling from the collections team about late payments on ' + ('your account.' if len(says) == 1 else str(len(says)) + ' of your products.')
        vars['debt_statement'] = head + ' ' + ' '.join(says)
    else:
        vars['debt_statement'] = ' '.join(says)
